        ["已加到左側工具欄"] = new[] { "已加到左側工具欄", "已加到左侧工具栏", "Added to the sidebar" },
        ["有未儲存嘅改動，儲存咗先離開？"] = new[] { "有未儲存的改動，是否儲存後離開？", "有未保存的改动，是否保存后离开？", "You have unsaved changes. Save before leaving?" },
