        ["睇權限並同意"] = new[] { "查看權限並同意", "查看权限并同意", "Review and allow permissions" },
        ["截圖超過 20000 張，之後唔再存"] = new[] { "截圖超過 20000 張，之後不再儲存", "截图超过 20000 张，之后不再保存", "More than 20,000 screenshots; no more will be saved" },
        ["工作坊"] = new[] { "工作坊", "工作坊", "Workshop" },
        ["✓ 已加到工具欄"] = new[] { "✓ 已加到工具欄", "✓ 已加到工具栏", "✓ In sidebar" },
        ["📌 加到工具欄"] = new[] { "📌 加到工具欄", "📌 加到工具栏", "📌 Add to sidebar" },
        ["重設位置及大細"] = new[] { "重設位置及大小", "重设位置及大小", "Reset position and size" },
        ["拖動"] = new[] { "拖動", "拖动", "Drag" },
        ["預覽音量（淨係影響預覽，唔會改影片）：撳喇叭靜音，拖或者用滾輪調"] = new[] { "預覽音量（只影響預覽，不會改變影片）：按喇叭靜音，拖曳或用滾輪調整", "预览音量（只影响预览，不会改变视频）：按喇叭静音，拖曳或用滚轮调整", "Preview volume (only affects the preview, not the video): click the speaker to mute, drag or scroll to adjust" },
        ["檔案修復"] = new[] { "檔案修復", "文件修复", "File Repair" },
        ["開唔到嘅影片、聲音、相片、ZIP / Word / Excel / PowerPoint、PDF 拖入嚟就自動修復，修好嘅另存一份。部分修復第一次用要下載免費開源工具（ffmpeg、qpdf、untrunc）。"] = new[] { "將無法開啟的影片、聲音、相片、ZIP / Word / Excel / PowerPoint、PDF 拖入即可自動修復，修復後另存一份。部分修復首次使用時需下載免費開源工具（ffmpeg、qpdf、untrunc）。", "将无法打开的视频、声音、相片、ZIP / Word / Excel / PowerPoint、PDF 拖入即可自动修复，修复后另存一份。部分修复首次使用时需下载免费开源工具（ffmpeg、qpdf、untrunc）。", "Drop in videos, audio, photos, ZIP / Word / Excel / PowerPoint files or PDFs that won't open and they're repaired automatically, saved as a new copy. Some repairs download free open-source tools (ffmpeg, qpdf, untrunc) the first time." },
        ["已修復"] = new[] { "已修復", "已修复", "repaired" },
        ["搵唔到檔案"] = new[] { "找不到檔案", "找不到文件", "File not found" },
        ["成個檔案入面全部係 0（資料已經冇咗，通常係當機或者儲存中途斷電），救唔返。"] = new[] { "整個檔案的內容全部是 0（資料已經遺失，通常是當機或儲存途中斷電），無法救回。", "整个文件的内容全部是 0（数据已经遗失，通常是当机或保存途中断电），无法救回。", "The whole file is zeros (the data is gone, usually from a crash or power loss while saving) and can't be recovered." },
        ["副檔名唔啱：其實係 {0} 檔（會用返啱嘅副檔名儲存）"] = new[] { "副檔名不正確：實際上是 {0} 檔（會以正確的副檔名儲存）", "扩展名不正确：实际上是 {0} 档（会以正确的扩展名保存）", "Wrong extension: it's actually a {0} file (it will be saved with the right extension)" },
        ["認唔到呢種檔案。支援：影片、聲音、相片、ZIP / Word / Excel / PowerPoint、PDF。"] = new[] { "無法辨識此類檔案。支援：影片、聲音、相片、ZIP / Word / Excel / PowerPoint、PDF。", "无法辨识此类文件。支持：视频、声音、相片、ZIP / Word / Excel / PowerPoint、PDF。", "Unrecognised file type. Supported: video, audio, photos, ZIP / Word / Excel / PowerPoint, PDF." },
        ["影片嘅索引（moov）唔見咗：通常係錄影中途斷電、當機或者手機冇電。"] = new[] { "影片的索引（moov）遺失了：通常是錄影途中斷電、當機或手機沒電。", "视频的索引（moov）遗失了：通常是录像途中断电、当机或手机没电。", "The video's index (moov) is missing: usually the recording was cut off by a power loss, crash or flat phone battery." },
        ["檔頭損壞，嘗試忽略錯誤讀取。"] = new[] { "檔頭損壞，嘗試略過錯誤讀取。", "档头损坏，尝试略过错误读取。", "The file header is damaged; trying to read it ignoring errors." },
        ["檢查損壞位置…"] = new[] { "檢查損壞位置…", "检查损坏位置…", "Checking for damage…" },
        ["發現約 {0} 處讀取錯誤（損壞嘅片段）。"] = new[] { "發現約 {0} 處讀取錯誤（損壞的片段）。", "发现约 {0} 处读取错误（损坏的片段）。", "Found about {0} read errors (damaged sections)." },
        ["讀取時冇發現明顯損壞。"] = new[] { "讀取時沒有發現明顯損壞。", "读取时没有发现明显损坏。", "No obvious damage found while reading." },
        ["重建索引…"] = new[] { "重建索引…", "重建索引…", "Rebuilding index…" },
        ["已重建檔案索引同時間戳（冇重新壓縮，畫質不變）。"] = new[] { "已重建檔案索引及時間戳（沒有重新壓縮，畫質不變）。", "已重建文件索引及时间戳（没有重新压缩，画质不变）。", "Rebuilt the file index and timestamps (no re-encoding, same quality)." },
        ["影片係 {0} 格式，部分播放器（例如未裝 HEVC 擴充功能嘅 Windows 播放器）播唔到：可以剔「轉做 H.264」再修一次。"] = new[] { "影片為 {0} 格式，部分播放器（例如未安裝 HEVC 擴充功能的 Windows 播放器）無法播放：可勾選「轉為 H.264」再修復一次。", "视频为 {0} 格式，部分播放器（例如未安装 HEVC 扩充功能的 Windows 播放器）无法播放：可勾选“转为 H.264”再修复一次。", "The video is {0}, which some players can't play (e.g. Windows without the HEVC extension): tick \"Convert to H.264\" and repair again." },
        ["重新壓縮…"] = new[] { "重新壓縮…", "重新压缩…", "Re-encoding…" },
        ["已重新壓縮成 H.264 / AAC：損壞嘅位置可能會有花屏或者跳格。"] = new[] { "已重新壓縮為 H.264 / AAC：損壞的位置可能會出現花屏或跳格。", "已重新压缩为 H.264 / AAC：损坏的位置可能会出现花屏或跳格。", "Re-encoded to H.264 / AAC: damaged spots may show glitches or skipped frames." },
        ["已轉做 H.264 / AAC（最兼容）。"] = new[] { "已轉為 H.264 / AAC（最兼容）。", "已转为 H.264 / AAC（最兼容）。", "Converted to H.264 / AAC (most compatible)." },
        ["已重新壓縮聲音：損壞嘅位置可能會有雜音或者跳咗。"] = new[] { "已重新壓縮聲音：損壞的位置可能會有雜音或跳過。", "已重新压缩声音：损坏的位置可能会有杂音或跳过。", "Re-encoded the audio: damaged spots may have noise or be skipped." },
        ["ffmpeg 讀唔到入面嘅影音資料，呢個檔案損壞得太嚴重。"] = new[] { "ffmpeg 無法讀取其中的影音資料，此檔案損壞得太嚴重。", "ffmpeg 无法读取其中的影音数据，此文件损坏得太严重。", "ffmpeg can't read any audio / video data; the file is too badly damaged." },
        ["用參考影片重建索引（可能要幾分鐘）…"] = new[] { "以參考影片重建索引（可能需時數分鐘）…", "以参考视频重建索引（可能需时数分钟）…", "Rebuilding the index from the reference video (may take a few minutes)…" },
        ["已用參考影片重建索引。最尾幾秒（未寫完嘅部分）可能會冇咗。"] = new[] { "已以參考影片重建索引。最後數秒（未寫入完成的部分）可能會遺失。", "已以参考视频重建索引。最后数秒（未写入完成的部分）可能会遗失。", "Rebuilt the index using the reference video. The last few seconds (not fully written) may be missing." },
        ["重建唔到：參考影片要係同一部機、同一個設定（解像度、FPS、格式）錄嘅正常影片，揀過另一條再試。"] = new[] { "無法重建：參考影片必須是同一部裝置、相同設定（解像度、FPS、格式）錄製的正常影片，請選擇另一條再試。", "无法重建：参考视频必须是同一部设备、相同设置（解像度、FPS、格式）录制的正常视频，请选择另一条再试。", "Couldn't rebuild: the reference must be a working video recorded on the same device with the same settings (resolution, FPS, format). Pick another one and try again." },
        ["已重新儲存相片。"] = new[] { "已重新儲存相片。", "已重新保存相片。", "Re-saved the photo." },
        ["已轉做 PNG（Windows 預設未必開到 {0}）。"] = new[] { "已轉為 PNG（Windows 預設未必能開啟 {0}）。", "已转为 PNG（Windows 默认未必能打开 {0}）。", "Converted to PNG (Windows may not open {0} by default)." },
        ["已重新解碼相片：損壞嘅部分可能會變灰色、綠色或者花咗。"] = new[] { "已重新解碼相片：損壞的部分可能會變成灰色、綠色或出現花紋。", "已重新解码相片：损坏的部分可能会变成灰色、绿色或出现花纹。", "Re-decoded the photo: damaged parts may turn grey, green or garbled." },
        ["讀唔到相片內容，呢個檔案損壞得太嚴重。"] = new[] { "無法讀取相片內容，此檔案損壞得太嚴重。", "无法读取相片内容，此文件损坏得太严重。", "Can't read the photo; the file is too badly damaged." },
        ["剪走咗檔頭前面嘅多餘資料。"] = new[] { "已移除檔頭前的多餘資料。", "已移除档头前的多余数据。", "Removed extra data before the file header." },
        ["相片唔完整（結尾唔見咗），已補返結尾。"] = new[] { "相片不完整（結尾遺失），已補回結尾。", "相片不完整（结尾遗失），已补回结尾。", "The photo was incomplete (the end was missing); added the end marker." },
        ["修正咗 PNG 檔頭。"] = new[] { "已修正 PNG 檔頭。", "已修正 PNG 档头。", "Fixed the PNG header." },
        ["修正咗 {0} 個校驗碼（CRC）錯誤。"] = new[] { "已修正 {0} 個校驗碼（CRC）錯誤。", "已修正 {0} 个校验码（CRC）错误。", "Fixed {0} checksum (CRC) errors." },
        ["相片唔完整（後半部分唔見咗）。"] = new[] { "相片不完整（後半部分遺失）。", "相片不完整（后半部分遗失）。", "The photo is incomplete (the second part is missing)." },
        ["救返 {0} / {1} 行，冇咗嘅部分用灰色補。"] = new[] { "救回 {0} / {1} 行，遺失的部分以灰色填補。", "救回 {0} / {1} 行，遗失的部分以灰色填补。", "Recovered {0} / {1} rows; the missing part is filled with grey." },
        ["檔案太大（超過 1.5 GB），暫時唔支援。"] = new[] { "檔案太大（超過 1.5 GB），暫時不支援。", "文件太大（超过 1.5 GB），暂时不支持。", "The file is too large (over 1.5 GB) and isn't supported yet." },
        ["ZIP 結構完整，冇發現損壞。如果開唔到，可能係程式版本太舊或者檔案有密碼。"] = new[] { "ZIP 結構完整，沒有發現損壞。如無法開啟，可能是程式版本太舊或檔案設有密碼。", "ZIP 结构完整，没有发现损坏。如无法打开，可能是程序版本太旧或文件设有密码。", "The ZIP structure is intact and no damage was found. If it won't open, the program may be too old or the file may have a password." },
        ["搵緊入面嘅檔案…"] = new[] { "正在尋找其中的檔案…", "正在寻找其中的文件…", "Looking for files inside…" },
        ["搵唔到任何可以救返嘅內容。"] = new[] { "找不到任何可救回的內容。", "找不到任何可救回的内容。", "Couldn't find anything that can be recovered." },
        ["重新砌過 ZIP：救返 {0} 個檔案。"] = new[] { "已重建 ZIP：救回 {0} 個檔案。", "已重建 ZIP：救回 {0} 个文件。", "Rebuilt the ZIP: recovered {0} files." },
        ["其中 {0} 個唔完整：{1}"] = new[] { "其中 {0} 個不完整：{1}", "其中 {0} 个不完整：{1}", "{0} of them are incomplete: {1}" },
        ["缺少 {0}：Office 可能仍然開唔到，可以試吓用 Office 嘅「開啟並修復」。"] = new[] { "缺少 {0}：Office 可能仍無法開啟，可嘗試使用 Office 的「開啟並修復」。", "缺少 {0}：Office 可能仍无法打开，可尝试使用 Office 的“打开并修复”。", "{0} is missing: Office may still not open it; try Office's \"Open and Repair\"." },
        ["PDF 唔完整（結尾唔見咗）。"] = new[] { "PDF 不完整（結尾遺失）。", "PDF 不完整（结尾遗失）。", "The PDF is incomplete (the end is missing)." },
        ["重建 PDF…"] = new[] { "重建 PDF…", "重建 PDF…", "Rebuilding PDF…" },
        ["已重建 PDF 嘅索引表。"] = new[] { "已重建 PDF 的索引表。", "已重建 PDF 的索引表。", "Rebuilt the PDF's index table." },
        ["PDF 結構冇明顯損壞，已重新整理一次。"] = new[] { "PDF 結構沒有明顯損壞，已重新整理一次。", "PDF 结构没有明显损坏，已刷新一次。", "No obvious damage in the PDF structure; it was rewritten once." },
        ["有 {0} 個警告：部分頁面或者圖片可能救唔返。"] = new[] { "有 {0} 個警告：部分頁面或圖片可能無法救回。", "有 {0} 个警告：部分页面或图片可能无法救回。", "{0} warnings: some pages or images may not be recoverable." },
        ["PDF 有密碼保護，要先用密碼開啟。"] = new[] { "PDF 設有密碼保護，須先以密碼開啟。", "PDF 设有密码保护，须先以密码打开。", "The PDF is password-protected; open it with the password first." },
        ["修唔到："] = new[] { "無法修復：", "无法修复：", "Couldn't repair: " },
        ["下載 {0}…"] = new[] { "下載 {0}…", "下载 {0}…", "Downloading {0}…" },
        ["下載咗但搵唔到程式檔"] = new[] { "已下載但找不到程式檔", "已下载但找不到程序档", "Downloaded, but the program file wasn't found" },
        ["將開唔到嘅檔案拖入嚟就會自動檢查同修復：影片、聲音、相片、ZIP / Word / Excel / PowerPoint、PDF。修好嘅檔案另存一份（名後面加「已修復」），唔會改原本嘅檔案。"] = new[] { "將無法開啟的檔案拖入即會自動檢查及修復：影片、聲音、相片、ZIP / Word / Excel / PowerPoint、PDF。修復後的檔案會另存一份（檔名後加上「已修復」），不會更改原本的檔案。", "将无法打开的文件拖入即会自动检查及修复：视频、声音、相片、ZIP / Word / Excel / PowerPoint、PDF。修复后的文件会另存一份（文件名后加上“已修复”），不会更改原本的文件。", "Drop files that won't open here and they're checked and repaired automatically: videos, audio, photos, ZIP / Word / Excel / PowerPoint, PDF. The repaired file is saved as a new copy (with \"repaired\" added to the name); the original is never changed." },
        ["影片一律轉做 H.264 / AAC（最兼容，但要重新壓縮，慢啲）"] = new[] { "影片一律轉為 H.264 / AAC（最兼容，但需重新壓縮，速度較慢）", "视频一律转为 H.264 / AAC（最兼容，但需重新压缩，速度较慢）", "Always convert videos to H.264 / AAC (most compatible, but re-encodes, so slower)" },
        ["選項"] = new[] { "選項", "选项", "Options" },
        ["修得到乜？"] = new[] { "可以修復甚麼？", "可以修复甚么？", "What can be repaired?" },
        ["• 影片 / 聲音：重建索引同時間戳、副檔名錯、播放器唔支援嘅格式（轉 H.264）、中間有損壞（重新壓縮，損壞位置可能有花屏）。\n"] = new[] { "• 影片／聲音：重建索引及時間戳、副檔名錯誤、播放器不支援的格式（轉為 H.264）、中間有損壞（重新壓縮，損壞位置可能出現花屏）。\n", "• 视频／声音：重建索引及时间戳、扩展名错误、播放器不支持的格式（转为 H.264）、中间有损坏（重新压缩，损坏位置可能出现花屏）。\n", "• Video / audio: rebuild the index and timestamps, wrong extension, formats players don't support (convert to H.264), damage in the middle (re-encode; damaged spots may glitch).\n" },
        ["• 錄影中途斷電 / 當機（MP4、MOV 冇咗索引）：要揀一條同一部機、同一個設定錄嘅正常影片做參考。\n"] = new[] { "• 錄影途中斷電／當機（MP4、MOV 遺失索引）：須選擇一條以同一部裝置、相同設定錄製的正常影片作參考。\n", "• 录像途中断电／当机（MP4、MOV 遗失索引）：须选择一条以同一部设备、相同设置录制的正常视频作参考。\n", "• Recording cut off by power loss / crash (MP4, MOV without an index): pick a working video recorded on the same device with the same settings as a reference.\n" },
        ["• 相片：JPEG / PNG 唔完整（冇咗嘅部分用灰色補）、校驗碼錯、副檔名錯；HEIC / WEBP 轉做 PNG。\n"] = new[] { "• 相片：JPEG／PNG 不完整（遺失的部分以灰色填補）、校驗碼錯誤、副檔名錯誤；HEIC／WEBP 轉為 PNG。\n", "• 相片：JPEG／PNG 不完整（遗失的部分以灰色填补）、校验码错误、扩展名错误；HEIC／WEBP 转为 PNG。\n", "• Photos: incomplete JPEG / PNG (missing part filled with grey), checksum errors, wrong extension; HEIC / WEBP converted to PNG.\n" },
        ["• ZIP / Word / Excel / PowerPoint / EPUB：由殘骸重新砌過，救返入面完好嘅檔案。\n"] = new[] { "• ZIP／Word／Excel／PowerPoint／EPUB：從殘餘資料重建，救回其中完好的檔案。\n", "• ZIP／Word／Excel／PowerPoint／EPUB：从残余数据重建，救回其中完好的文件。\n", "• ZIP / Word / Excel / PowerPoint / EPUB: rebuilt from what's left, recovering the intact files inside.\n" },
