        ["對話同附件都唔會儲存。"] = new[] { "對話及附件均不會儲存。", "对话及附件均不会保存。", "This chat and its attachments are not saved." },
        ["而家用緊嘅本機 AI 睇唔到圖片：會改用文字辨識讀出圖入面嘅字再交俾 AI；想 AI 真係睇圖，請去「AI 助手」頁改用 Claude / ChatGPT / Gemini。"] = new[] { "目前使用的本機 AI 無法查看圖片：會改用文字辨識讀出圖片中的文字再交給 AI；如想 AI 真正看圖，請到「AI 助手」頁改用 Claude / ChatGPT / Gemini。", "目前使用的本机 AI 无法查看图片：会改用文本辨识读出图片中的文本再交给 AI；如想 AI 真正看图，请到“AI 助手”页改用 Claude / ChatGPT / Gemini。", "The local AI in use can't see images: text recognition will read the text in the image and pass it to the AI instead. For real image understanding, switch to Claude / ChatGPT / Gemini on the AI Assistant page." },
        ["本機 AI 睇唔到圖片，已經改用文字辨識讀出圖入面嘅字。圖入面冇字嘅內容（相、圖表）AI 係唔知嘅。"] = new[] { "本機 AI 無法查看圖片，已改用文字辨識讀出圖片中的文字。圖片中沒有文字的內容（相片、圖表）AI 並不知道。", "本机 AI 无法查看图片，已改用文本辨识读出图片中的文本。图片中没有文本的内容（相片、图表）AI 并不知道。", "The local AI can't see images, so text recognition was used to read the text in them. The AI doesn't know about anything in the image that isn't text (photos, charts)." },
        ["本機 AI 睇唔到圖片：有啲圖讀到入面嘅字，有啲讀唔到。想 AI 真係睇圖，請去「AI 助手」頁改用 Claude / ChatGPT / Gemini。"] = new[] { "本機 AI 無法查看圖片：部分圖片讀到文字，部分讀不到。如想 AI 真正看圖，請到「AI 助手」頁改用 Claude / ChatGPT / Gemini。", "本机 AI 无法查看图片：部分图片读到文本，部分读不到。如想 AI 真正看图，请到“AI 助手”页改用 Claude / ChatGPT / Gemini。", "The local AI can't see images: text could be read from some of them but not others. For real image understanding, switch to Claude / ChatGPT / Gemini on the AI Assistant page." },
        ["本機 AI 睇唔到圖片，圖入面亦讀唔到字。想 AI 睇圖，請去「AI 助手」頁改用 Claude / ChatGPT / Gemini。"] = new[] { "本機 AI 無法查看圖片，圖片中亦讀不到文字。如想 AI 看圖，請到「AI 助手」頁改用 Claude / ChatGPT / Gemini。", "本机 AI 无法查看图片，图片中亦读不到文本。如想 AI 看图，请到“AI 助手”页改用 Claude / ChatGPT / Gemini。", "The local AI can't see images, and no text could be read from them. To have the AI look at images, switch to Claude / ChatGPT / Gemini on the AI Assistant page." },
        ["{0} 唔識睇圖片。"] = new[] { "{0} 無法查看圖片。", "{0} 无法查看图片。", "{0} can't see images." },
