        ["搵唔到圖片識別組件。"] = new[] { "找不到圖片識別組件。", "找不到图片识别组件。", "Image recognition add-on not found." },
        ["下載圖片識別組件（{0}）…"] = new[] { "正在下載圖片識別組件（{0}）…", "正在下载图片识别组件（{0}）…", "Downloading image recognition add-on ({0})…" },
        ["圖片識別模型開唔到。"] = new[] { "圖片識別模型無法啟動。", "图片识别模型无法启动。", "The image recognition model couldn't start." },
        ["而家用緊嘅本地 AI（{0}）識睇圖片，但未下載「圖片識別組件」，所以暫時睇唔到你附加嘅圖片。\n\n而家去下載？"] = new[] { "目前使用的本地 AI（{0}）支援查看圖片，但尚未下載「圖片識別組件」，所以暫時看不到你附加的圖片。\n\n現在前往下載？", "目前使用的本地 AI（{0}）支持查看图片，但尚未下载“图片识别组件”，所以暂时看不到你附加的图片。\n\n现在前往下载？", "The local AI in use ({0}) supports images, but its image recognition add-on isn't downloaded yet, so it can't see the image you attached.\n\nDownload it now?" },
        ["而家用緊嘅本地 AI（{0}）唔識睇圖片。可以下載一個細嘅「圖片識別模型」幫佢睇圖。\n\n而家去下載？"] = new[] { "目前使用的本地 AI（{0}）無法查看圖片。可以下載一個小型的「圖片識別模型」協助它看圖。\n\n現在前往下載？", "目前使用的本地 AI（{0}）无法查看图片。可以下载一个小型的“图片识别模型”协助它看图。\n\n现在前往下载？", "The local AI in use ({0}) can't see images. You can download a small image recognition model to look at images for it.\n\nDownload one now?" },
