        ["✓ 而家嘅本地 AI（{0}）唔識睇圖，會借 {1} 幫手睇圖。"] = new[] { "✓ 目前的本地 AI（{0}）不支援看圖，會借用 {1} 協助看圖。", "✓ 目前的本地 AI（{0}）不支持看图，会借用 {1} 协助看图。", "✓ The current local AI ({0}) is text-only; {1} looks at images for it." },
        ["而家嘅本地 AI（{0}）識睇圖片，但未裝圖片識別組件：撳下面「加裝」。"] = new[] { "目前的本地 AI（{0}）支援看圖，但未安裝圖片識別組件：請按下面的「加裝」。", "目前的本地 AI（{0}）支持看图，但未安装图片识别组件：请按下面的“加装”。", "The current local AI ({0}) supports images but its add-on isn't installed: click “Add” below." },
        ["而家嘅本地 AI（{0}）唔識睇圖片：下載下面一個模型幫手睇圖。"] = new[] { "目前的本地 AI（{0}）不支援看圖：請下載下面其中一個模型協助看圖。", "目前的本地 AI（{0}）不支持看图：请下载下面其中一个模型协助看图。", "The current local AI ({0}) can't see images: download a model below to look at images for it." },
        ["+ 圖片識別組件 ≈ {0:0.0} GB"] = new[] { "+ 圖片識別組件 ≈ {0:0.0} GB", "+ 图片识别组件 ≈ {0:0.0} GB", "+ image add-on ≈ {0:0.0} GB" },
        ["✓ 已下載模型，未裝圖片識別組件"] = new[] { "✓ 已下載模型，未安裝圖片識別組件", "✓ 已下载模型，未安装图片识别组件", "✓ Model downloaded, image add-on not installed" },
