        ["✓ 用緊嚟幫手睇圖"] = new[] { "✓ 正用來協助看圖", "✓ 正用来协助看图", "✓ Looking at images for the current AI" },
        ["✓ 已下載，睇到圖片"] = new[] { "✓ 已下載，可以看圖", "✓ 已下载，可以看图", "✓ Downloaded, sees images" },
