        ["睇每個磁碟剩幾多位同硬碟健康，搵出邊個資料夾最食位、邊啲檔案重複咗；管理開機自動行嘅程式，睇晒已安裝嘅軟件同解除安裝。"] = new[] { "查看每個磁碟的剩餘空間及硬碟健康，找出最佔空間的資料夾及重複的檔案；管理開機自動執行的程式，查看所有已安裝的軟件並解除安裝。", "查看每个磁盘的剩余空间及硬盘健康，找出最占空间的文件夹及重复的文件；管理开机自动运行的程序，查看所有已安装的软件并卸载。", "See free space and drive health, find the folders that use the most space and duplicate files, manage programs that start with Windows, and review or uninstall installed software." },
        ["一次過處理好多張圖：縮細、壓縮、轉格式、自動調整光暗、銳化、加水印、改名、清除相片入面嘅位置資料。原圖唔會被改。"] = new[] { "一次處理多張圖片：縮小、壓縮、轉換格式、自動調整光暗、銳化、加水印、重新命名、清除相片中的位置資料。原圖不會被修改。", "一次处理多张图片：缩小、压缩、转换格式、自动调整光暗、锐化、加水印、重命名、清除相片中的位置数据。原图不会被修改。", "Process many images at once: resize, compress, convert, auto-adjust levels, sharpen, watermark, rename and strip location data from photos. Originals are never changed." },
        ["產生二維碼（文字、網址、Wi-Fi、聯絡人），或者框住畫面、揀圖片讀取二維碼。全部喺你部機做，唔使上網。"] = new[] { "產生二維碼（文字、網址、Wi-Fi、聯絡人），或框選畫面、選擇圖片讀取二維碼。全部在你的電腦上處理，無須上網。", "产生二维码（文本、网址、Wi-Fi、联系人），或框选画面、选择图片读取二维码。全部在你的电脑上处理，无须上网。", "Create QR codes (text, links, Wi-Fi, contacts) or read one from the screen or an image. Everything runs on your PC, no internet needed." },
        ["喺畫面上面畫一個框，框入面嘅字一變就即時翻譯，遊戲、影片、網頁都得。用 Windows 內置文字辨識加你揀咗嘅 AI（本地 AI 都得）。"] = new[] { "在畫面上畫一個框，框內的文字一變就即時翻譯，遊戲、影片、網頁都可以。使用 Windows 內置文字辨識及你選擇的 AI（本地 AI 亦可）。", "在画面上画一个框，框内的文本一变就即时翻译，游戏、视频、网页都可以。使用 Windows 内置文本辨识及你选择的 AI（本地 AI 亦可）。", "Draw a box on the screen and the text inside is translated as soon as it changes — games, videos, web pages. Uses Windows' built-in text recognition plus the AI you chose (local AI works too)." },
        ["記低每日收支，按月睇總數同每類用咗幾多，可以匯出 CSV。資料只存喺你部電腦。"] = new[] { "記錄每日收支，按月查看總數及各類別支出，可匯出 CSV。資料只儲存在你的電腦。", "记录每日收支，按月查看总数及各类别支出，可导出 CSV。数据只保存在你的电脑。", "Record daily income and spending, see monthly totals and spending by category, and export to CSV. Data stays on your PC." },
        ["長度、重量、溫度、面積、容量、速度等單位互換（離線）；匯率用免費公開嘅每日數據，唔使 AI、唔使帳戶。"] = new[] { "長度、重量、溫度、面積、容量、速度等單位互換（離線）；匯率使用免費公開的每日數據，無須 AI、無須帳戶。", "长度、重量、温度、面积、容量、速度等单位互换（脱机）；汇率使用免费公开的每日数据，无须 AI、无须帐户。", "Convert length, weight, temperature, area, volume, speed and more (offline); exchange rates use free public daily data, with no AI and no account." },
        ["畫面翻譯：畫框開始 / 停止翻譯"] = new[] { "畫面翻譯：畫框開始／停止翻譯", "画面翻译：画框开始／停止翻译", "Screen Translator: draw a box to start / stop" },
        ["未加入圖片：撳「加入圖片…」或者將圖片 / 資料夾拖入嚟。"] = new[] { "尚未加入圖片：按「加入圖片…」或將圖片／資料夾拖進來。", "尚未加入图片：按“加入图片…”或将图片／文件夹拖进来。", "No images yet: click “Add images…” or drag images or folders here." },
        ["一次過處理好多張圖：縮細、轉格式、修靚、加水印、改名、清除相片資料。原圖唔會被改，處理好嘅另存一份。支援 JPG、PNG、BMP、GIF、TIFF。"] = new[] { "一次處理多張圖片：縮小、轉換格式、修飾、加水印、重新命名、清除相片資料。原圖不會被修改，處理後另存一份。支援 JPG、PNG、BMP、GIF、TIFF。", "一次处理多张图片：缩小、转换格式、修饰、加水印、重命名、清除相片数据。原图不会被修改，处理后另存一份。支持 JPG、PNG、BMP、GIF、TIFF。", "Process many images at once: resize, convert, enhance, watermark, rename and strip photo data. Originals are never changed; results are saved as new files. Supports JPG, PNG, BMP, GIF and TIFF." },
