        ["要按比例準確列印，請在列印視窗選擇相同的紙張大小，邊界設為「無」，縮放設為 100%。"] = new[] { "要按比例準確列印，請在列印視窗選擇相同的紙張大小，邊界設為「無」，縮放設為 100%。", "要按比例准确打印，请在打印窗口选择相同的纸张大小，边界设为“无”，缩放设为 100%。", "For an accurate scale, choose the same paper size in the print window, set margins to “None” and scale to 100%." },
        ["繪圖"] = new[] { "繪圖", "绘图", "Drafting" },
        ["圖面"] = new[] { "圖面", "图面", "Drawing" },
        ["2D 製圖：直線、聚合線、圓、弧、文字同尺寸標註；圖層、物件捕捉、指令列（L、C、M、TR…）；移動、複製、旋轉、鏡射、偏移、修剪、延伸、圓角。支援開啟同儲存 DXF，可以匯出 SVG / PNG，按比例列印。"] = new[] { "2D 製圖：直線、聚合線、圓、弧、文字和尺寸標註；圖層、物件捕捉、指令列（L、C、M、TR…）；移動、複製、旋轉、鏡射、偏移、修剪、延伸、圓角。支援開啟和儲存 DXF，可以匯出 SVG / PNG，按比例列印。", "2D 制图：直线、聚合线、圆、弧、文本和尺寸标注；图层、对象捕捉、指令列（L、C、M、TR…）；移动、拷贝、旋转、镜射、偏移、修剪、延伸、圆角。支持打开和保存 DXF，可以导出 SVG / PNG，按比例打印。", "2D drafting: lines, polylines, circles, arcs, text and dimensions; layers, object snap and a command line (L, C, M, TR…); move, copy, rotate, mirror, offset, trim, extend and fillet. Opens and saves DXF, exports SVG / PNG and prints to scale." },
        ["註解"] = new[] { "註解", "注解", "Annotate" },
        ["公用程式"] = new[] { "公用程式", "公用程序", "Utilities" },
        ["剪貼簿"] = new[] { "剪貼簿", "剪贴板", "Clipboard" },
        ["測量"] = new[] { "測量", "测量", "Measure" },
        ["將開唔到嘅檔案拖入嚟就會自動檢查同修復：影片、聲音、相片、ZIP / 文件 / 試算表 / 簡報、PDF。修好嘅檔案另存一份（名後面加「已修復」），唔會改原本嘅檔案。"] = new[] { "將無法開啟的檔案拖入即會自動檢查及修復：影片、聲音、相片、ZIP / 文件 / 試算表 / 簡報、PDF。修復後的檔案會另存一份（檔名後加上「已修復」），不會更改原本的檔案。", "将无法打开的文件拖入即会自动检查及修复：视频、声音、相片、ZIP / 文档 / 电子表格 / 演示文稿、PDF。修复后的文件会另存一份（文件名后加上“已修复”），不会更改原本的文件。", "Drop files that won't open here and they're checked and repaired automatically: videos, audio, photos, ZIP / documents / spreadsheets / presentations, PDF. The repaired file is saved as a new copy (with \"repaired\" added to the name); the original is never changed." },
        ["• ZIP / 文件 / 試算表 / 簡報 / EPUB：由殘骸重新砌過，救返入面完好嘅檔案。\n"] = new[] { "• ZIP／文件／試算表／簡報／EPUB：從殘餘資料重建，救回其中完好的檔案。\n", "• ZIP／文档／电子表格／演示文稿／EPUB：从残余数据重建，救回其中完好的文件。\n", "• ZIP / documents / spreadsheets / presentations / EPUB: rebuilt from what's left, recovering the intact files inside.\n" },
        ["開唔到嘅影片、聲音、相片、ZIP / 文件 / 試算表 / 簡報、PDF 拖入嚟就自動修復，修好嘅另存一份。部分修復第一次用要下載免費開源工具（ffmpeg、qpdf、untrunc）。"] = new[] { "將無法開啟的影片、聲音、相片、ZIP / 文件 / 試算表 / 簡報、PDF 拖入即可自動修復，修復後另存一份。部分修復首次使用時需下載免費開源工具（ffmpeg、qpdf、untrunc）。", "将无法打开的视频、声音、相片、ZIP / 文档 / 电子表格 / 演示文稿、PDF 拖入即可自动修复，修复后另存一份。部分修复首次使用时需下载免费开源工具（ffmpeg、qpdf、untrunc）。", "Drop in videos, audio, photos, ZIP / documents / spreadsheets / presentations or PDFs that won't open and they're repaired automatically, saved as a new copy. Some repairs download free open-source tools (ffmpeg, qpdf, untrunc) the first time." },
        ["認唔到呢種檔案。支援：影片、聲音、相片、ZIP / 文件 / 試算表 / 簡報、PDF。"] = new[] { "無法辨識此類檔案。支援：影片、聲音、相片、ZIP / 文件 / 試算表 / 簡報、PDF。", "无法辨识此类文件。支持：视频、声音、相片、ZIP / 文档 / 电子表格 / 演示文稿、PDF。", "Unrecognised file type. Supported: video, audio, photos, ZIP / documents / spreadsheets / presentations, PDF." },
        ["影音：影片、聲音、圖片互轉（MP4、GIF、MP3、PNG…），剪頭尾同縮細，第一次用要下載 ffmpeg（~100 MB）。文件：試算表、CSV、TSV、JSON 互轉，修正 CSV 中文亂碼。"] = new[] { "影音：影片、聲音、圖片互相轉換（MP4、GIF、MP3、PNG…），剪輯頭尾及縮小，首次使用需下載 ffmpeg（~100 MB）。文件：試算表、CSV、TSV、JSON 互相轉換，修正 CSV 中文亂碼。", "影音：视频、声音、图片互相转换（MP4、GIF、MP3、PNG…），剪辑头尾及缩小，首次使用需下载 ffmpeg（~100 MB）。文档：电子表格、CSV、TSV、JSON 互相转换，修正 CSV 中文乱码。", "Media: convert video, audio and images (MP4, GIF, MP3, PNG…), trim and downscale — first use downloads ffmpeg (~100 MB). Documents: convert between spreadsheets, CSV, TSV and JSON and fix garbled Chinese in CSVs." },
        ["舊版 .xls 唔支援：請先另存做 .xlsx"] = new[] { "不支援舊版 .xls：請先另存為 .xlsx", "不支持旧版 .xls：请先另存为 .xlsx", "Old .xls isn't supported: save it as .xlsx first" },
        ["UTF-8（試算表軟件開到中文，建議）"] = new[] { "UTF-8（試算表軟件可正常顯示中文，建議）", "UTF-8（电子表格软件可正常显示中文，建议）", "UTF-8 (opens correctly in spreadsheet apps, recommended)" },
