        ["搵唔到呢個模型（{0}），或者佢要登入先睇到。"] = new[] { "找不到此模型（{0}），或需要登入才能檢視。", "找不到此模型（{0}），或需要登录才能查看。", "Model not found ({0}), or it requires signing in." },
        ["呢個模型要登入 Hugging Face 同意條款先下載到，暫時未支援。"] = new[] { "此模型需要登入 Hugging Face 並同意條款才能下載，暫時未支援。", "此模型需要登录 Hugging Face 并同意条款才能下载，暂时未支持。", "This model requires signing in to Hugging Face and accepting its terms before downloading, which isn't supported yet." },
        ["呢個模型冇 GGUF 檔案。本地 AI 只支援 GGUF 格式嘅模型。"] = new[] { "此模型沒有 GGUF 檔案。本地 AI 只支援 GGUF 格式的模型。", "此模型没有 GGUF 文件。本地 AI 只支持 GGUF 格式的模型。", "This model has no GGUF file. Local AI only supports models in GGUF format." },
        ["呢個模型分成幾個檔案，暫時未支援。"] = new[] { "此模型分成多個檔案，暫時未支援。", "此模型分成多个文件，暂时未支持。", "This model is split into several files, which isn't supported yet." },
        ["自訂模型（進階）：貼上 Hugging Face 模型網址，或者 .gguf 檔案嘅直接連結"] = new[] { "自訂模型（進階）：貼上 Hugging Face 模型網址，或 .gguf 檔案的直接連結", "自订模型（高端）：粘贴 Hugging Face 模型网址，或 .gguf 文件的直接链接", "Custom model (advanced): paste a Hugging Face model URL or a direct link to a .gguf file" },
