        ["加入自訂模型：{0}　{1}\n來源：{2}\n授權：{3}"] = new[] { "加入自訂模型：{0}　{1}\n來源：{2}\n授權：{3}", "加入自订模型：{0}　{1}\n来源：{2}\n授权：{3}", "Add custom model: {0}  {1}\nSource: {2}\nLicence: {3}" },
        ["未註明"] = new[] { "未註明", "未注明", "not stated" },
        ["自訂模型由第三方提供，{0} 冇檢查過佢嘅內容、質素同授權。可唔可以使用（包括商業用途）請自行查閱模型頁嘅授權條款；下載同使用嘅風險由你自行承擔。"] = new[] { "自訂模型由第三方提供，{0} 並未檢查其內容、質素及授權。能否使用（包括商業用途）請自行查閱模型頁的授權條款；下載及使用的風險由你自行承擔。", "自订模型由第三方提供，{0} 并未检查其内容、质素及授权。能否使用（包括商业用途）请自行查阅模型页的授权条款；下载及使用的风险由你自行承担。", "Custom models come from third parties; {0} has not checked their content, quality or licence. Check the licence terms on the model page yourself to see whether you may use it (including commercially); you download and use it at your own risk." },
        ["加入並下載？"] = new[] { "加入並下載？", "加入并下载？", "Add and download?" },
        ["自訂模型"] = new[] { "自訂模型", "自订模型", "Custom model" },
