        ["寫低你想留意嘅內容（例如「電競比賽」）。之後每收到一封新郵件，AI 都會睇一次；同你寫嘅內容有關就會彈 Windows 通知。"] = new[] { "寫下你想留意的內容（例如「電競比賽」）。之後每收到一封新郵件，AI 都會閱讀一次；與你所寫的內容有關便會顯示 Windows 通知。", "写下你想留意的内容（例如“电竞比赛”）。之后每收到一封新邮件，AI 都会阅读一次；与你所写的内容有关便会显示 Windows 通知。", "Write down what you want to watch for (e.g. “esports tournaments”). From then on the AI reads every new email once, and shows a Windows notification when it is related." },
        ["要開住程式先會檢查。每封新郵件會用一次你揀咗嘅 AI（郵件內容會交俾嗰個 AI 判斷）；一次過收到好多封時只會睇最新 10 封。"] = new[] { "程式開啟時才會檢查。每封新郵件會使用一次你所選的 AI（郵件內容會交給該 AI 判斷）；一次過收到大量郵件時只會閱讀最新 10 封。", "程序打开时才会检查。每封新邮件会使用一次你所选的 AI（邮件内容会交给该 AI 判断）；一次过收到大量邮件时只会阅读最新 10 封。", "Checking only happens while the app is open. Each new email uses your chosen AI once (the email content is sent to that AI to judge); when many arrive at once, only the newest 10 are read." },
        ["監聽內容，例如：電競比賽"] = new[] { "監聽內容，例如：電競比賽", "监听内容，例如：电竞比赛", "What to watch for, e.g. esports tournaments" },
        ["監聽內容（剔咗 = 開啟）"] = new[] { "監聽內容（已剔選 = 開啟）", "监听内容（已剔选 = 打开）", "Watch items (ticked = on)" },
        ["未有監聽內容。喺上面輸入再撳「新增」。"] = new[] { "尚未有監聽內容。請在上方輸入後按「新增」。", "尚未有监听内容。请在上方输入后按“添加”。", "Nothing to watch yet. Type above and click “Add”." },
        ["✓ 已設定 Discord：符合時 Discord 亦會收到通知。"] = new[] { "✓ 已設定 Discord：符合時 Discord 亦會收到通知。", "✓ 已设置 Discord：符合时 Discord 亦会收到通知。", "✓ Discord is set up: matches are sent to Discord as well." },
        ["未設定 Discord（設定 → 通知）：只會彈 Windows 通知。"] = new[] { "未設定 Discord（設定 → 通知）：只會顯示 Windows 通知。", "未设置 Discord（设置 → 通知）：只会显示 Windows 通知。", "Discord isn’t set up (Settings → Notifications): only Windows notifications are shown." },
