        ["撳住拖曳，隨手圈出範圍。Shift = 加入、Alt = 減去。"] = new[] { "按住並拖曳，徒手圈出範圍。Shift = 加入、Alt = 減去。", "按住并拖曳，徒手圈出范围。Shift = 加入、Alt = 减去。", "Hold and drag to draw a freehand selection. Shift = add, Alt = subtract." },
