        ["用前景色畫。[ ] 改大細；Shift + 撳 = 由上一筆畫直線。支援手寫筆壓力。"] = new[] { "以前景色繪畫。[ ] 調整大小；Shift + 按一下 = 由上一筆畫直線。支援手寫筆壓力。", "以前景色绘画。[ ] 调整大小；Shift + 按一下 = 由上一笔画直线。支持手写笔压力。", "Paint with the foreground color. [ ] changes size; Shift + click draws a straight line from the last stroke. Supports pen pressure." },
        ["擦走而家圖層嘅內容（變透明）。[ ] 改大細。"] = new[] { "擦除目前圖層的內容（變為透明）。[ ] 調整大小。", "擦除目前图层的内容（变为透明）。[ ] 调整大小。", "Erase the current layer to transparency. [ ] changes size." },
        ["撳一下用前景色填滿顏色相近嘅位置。"] = new[] { "按一下以前景色填滿顏色相近的區域。", "按一下以前景色填满颜色相近的区域。", "Click to fill areas of similar color with the foreground color." },
        ["撳一下攞畫面上嘅顏色做前景色；Alt + 撳 = 背景色。"] = new[] { "按一下取得畫面上的顏色作為前景色；Alt + 按一下 = 背景色。", "按一下取得画面上的颜色作为前景色；Alt + 按一下 = 背景色。", "Click to pick a color as the foreground color; Alt + click sets the background color." },
