        ["撳一下開始打字；撳現有文字就修改。Esc 完成。"] = new[] { "按一下開始輸入文字；按現有文字即可修改。Esc 完成。", "按一下开始输入文本；按现有文本即可修改。Esc 完成。", "Click to start typing; click existing text to edit it. Esc to finish." },
