        ["拖曳畫矩形；撳一下輸入大細。Shift = 正方形，Alt = 由中間開始。"] = new[] { "拖曳繪製矩形；按一下輸入尺寸。Shift = 正方形，Alt = 由中心開始。", "拖曳绘制矩形；按一下输入尺寸。Shift = 正方形，Alt = 由中心开始。", "Drag to draw a rectangle; click to enter a size. Shift = square, Alt = from the center." },
        ["拖曳畫橢圓；撳一下輸入大細。Shift = 正圓，Alt = 由中間開始。"] = new[] { "拖曳繪製橢圓；按一下輸入尺寸。Shift = 正圓，Alt = 由中心開始。", "拖曳绘制椭圆；按一下输入尺寸。Shift = 正圆，Alt = 由中心开始。", "Drag to draw an ellipse; click to enter a size. Shift = circle, Alt = from the center." },
