        ["仿製印章"] = new[] { "仿製印章", "仿制印章", "Clone Stamp" },
        ["漸層"] = new[] { "漸層", "渐层", "Gradient" },
        ["橢圓形"] = new[] { "橢圓形", "椭圆形", "Ellipse" },
        ["逐點撳出多邊形；撳返起點、雙擊或者 Enter 完成，Backspace 刪最後一點，Esc 取消。Shift = 45°。"] = new[] { "逐點點擊繪出多邊形；點回起點、按兩下或按 Enter 完成，Backspace 刪除最後一點，Esc 取消。Shift = 45°。", "逐点点击绘出多边形；点回起点、按两下或按 Enter 完成，Backspace 删除最后一点，Esc 取消。Shift = 45°。", "Click to add corners; click the first point, double-click or press Enter to finish. Backspace removes the last point, Esc cancels. Shift = 45°." },
        ["拖曳四邊同四角調整範圍，拖入面移動；Enter 或雙擊裁切，Esc 還原。Shift = 保持比例。"] = new[] { "拖曳四邊及四角調整範圍，拖曳內部移動；按 Enter 或按兩下裁切，Esc 還原。Shift = 保持比例。", "拖曳四边及四角调整范围，拖曳内部移动；按 Enter 或按两下裁切，Esc 还原。Shift = 保持比例。", "Drag the edges and corners to adjust, drag inside to move. Enter or double-click crops, Esc resets. Shift keeps the ratio." },
        ["冇柔邊嘅實心筆，啱畫像素圖。[ ] 改大細；Alt + 撳 = 吸色。"] = new[] { "無柔邊的實心筆，適合繪製像素圖。[ ] 更改大小；Alt + 點擊 = 取色。", "无柔边的实心笔，适合绘制像素图。[ ] 更改大小；Alt + 点击 = 取色。", "Hard-edged pen for pixel art. [ ] changes size; Alt + click picks a color." },
        ["Alt + 撳設定取樣點，再喺其他位置畫，就會複製取樣點嘅內容。"] = new[] { "Alt + 點擊設定取樣點，再於其他位置繪畫，即會複製取樣點的內容。", "Alt + 点击设置采样点，再于其他位置绘画，即会拷贝采样点的内容。", "Alt + click to set the source, then paint elsewhere to copy from it." },
        ["拖曳拉出漸層（前景色到背景色）。Shift = 45°；有選取範圍就只填入面。"] = new[] { "拖曳拉出漸層（前景色到背景色）。Shift = 45°；有選取範圍時只填入範圍內。", "拖曳拉出渐层（前景色到背景色）。Shift = 45°；有选取范围时只填入范围内。", "Drag to draw a gradient (foreground to background). Shift = 45°; fills only the selection if there is one." },
        ["撳一下開始打字；撳現有文字可以再改。Ctrl + Enter 完成，Esc 取消。"] = new[] { "點擊開始輸入文字；點擊現有文字可再修改。Ctrl + Enter 完成，Esc 取消。", "点击开始输入文本；点击现有文本可再修改。Ctrl + Enter 完成，Esc 取消。", "Click to start typing; click existing text to edit it. Ctrl + Enter commits, Esc cancels." },
        ["拖曳畫矩形（自動開新圖層）。Shift = 正方形，Alt = 由中心畫。"] = new[] { "拖曳繪製矩形（自動建立新圖層）。Shift = 正方形，Alt = 從中心繪製。", "拖曳绘制矩形（自动创建新图层）。Shift = 正方形，Alt = 从中心绘制。", "Drag to draw a rectangle on a new layer. Shift = square, Alt = from the center." },
